import { useState, type FormEvent, type ChangeEvent, type ReactNode } from "react";
import { ChevronDownIcon, CpuChipIcon, GlobeAltIcon, LinkIcon, LockClosedIcon, ShieldCheckIcon, XMarkIcon, EyeIcon, EyeSlashIcon } from "@heroicons/react/24/outline";
import type { ExtendedMikrotikConnectionCreate, ExtendedMikrotikConnection, MikrotikDevice } from "../types/mikrotikConnections";

interface Props { open: boolean; editingConnection: ExtendedMikrotikConnection | null; form: ExtendedMikrotikConnectionCreate; devices: MikrotikDevice[]; loading: boolean; onFormChange: (form: ExtendedMikrotikConnectionCreate) => void; onClose: () => void; onSubmit: (event: FormEvent<HTMLFormElement>) => void; }
const inputClass = "w-full rounded-xl border border-slate-200 bg-slate-50 px-3 py-2.5 text-sm text-slate-800 outline-none transition placeholder:text-slate-400 focus:border-sky-400 focus:ring-2 focus:ring-sky-100 dark:border-slate-700 dark:bg-gray-900 dark:text-white dark:focus:ring-sky-950";
function Field({ label, children }: { label: string; children: ReactNode }) { return <label className="block min-w-0 space-y-1.5"><span className="block text-xs font-semibold text-slate-600 dark:text-slate-300">{label}</span>{children}</label>; }
function Section({ title, description, icon, defaultOpen = false, children }: { title: string; description: string; icon: ReactNode; defaultOpen?: boolean; children: ReactNode }) {
  return <details open={defaultOpen} className="group rounded-xl border border-slate-200 bg-white dark:border-slate-700 dark:bg-slate-900/60"><summary className="flex cursor-pointer list-none items-center gap-3 p-3.5 sm:p-4 [&::-webkit-details-marker]:hidden"><span className="flex h-9 w-9 shrink-0 items-center justify-center rounded-xl bg-gradient-to-br from-sky-100 to-emerald-100 text-sky-700 dark:from-sky-950 dark:to-emerald-950 dark:text-sky-300">{icon}</span><span className="min-w-0 flex-1"><span className="block text-sm font-bold text-slate-800 dark:text-slate-100">{title}</span><span className="mt-0.5 block text-xs text-slate-500 dark:text-slate-400">{description}</span></span><ChevronDownIcon className="h-4 w-4 shrink-0 text-slate-400 transition-transform group-open:rotate-180" /></summary><div className="space-y-4 border-t border-slate-100 p-3.5 sm:p-4 dark:border-slate-800">{children}</div></details>;
}
export default function ConnectionFormAccordion({ open, editingConnection, form, devices, loading, onFormChange, onClose, onSubmit }: Props) {
  const [showPassword, setShowPassword] = useState(false);
  if (!open) return null;
  const update = (event: ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    const target = event.target;
    const value: string | number | boolean = target instanceof HTMLInputElement && target.type === "checkbox" ? target.checked : target.name === "port" ? Number(target.value) : target.value;
    if (target.name === "use_ssl") { const enabled = Boolean(value); onFormChange({ ...form, use_ssl: enabled, port: enabled ? 8729 : 8728 }); return; }
    onFormChange({ ...form, [target.name]: value });
  };
  return <div className="fixed inset-0 z-50 flex items-end justify-center bg-slate-950/50 p-0 backdrop-blur-sm sm:items-center sm:p-4"><section role="dialog" aria-modal="true" aria-labelledby="connection-form-title" className="max-h-[95dvh] w-full max-w-2xl overflow-y-auto rounded-t-2xl border border-slate-200 bg-slate-50 shadow-2xl sm:rounded-2xl dark:border-slate-700 dark:bg-gray-950">
    <header className="sticky top-0 z-10 flex items-center justify-between gap-3 border-b border-slate-200 bg-white/95 p-4 backdrop-blur sm:p-5 dark:border-slate-700 dark:bg-gray-900/95"><div className="flex min-w-0 items-center gap-3"><div className="rounded-xl bg-gradient-to-br from-sky-100 to-emerald-100 p-2.5 text-sky-700 dark:from-sky-950 dark:to-emerald-950 dark:text-sky-300"><CpuChipIcon className="h-5 w-5" /></div><div className="min-w-0"><h2 id="connection-form-title" className="truncate text-base font-extrabold text-slate-900 dark:text-white">{editingConnection ? "Edit connection" : "Add MikroTik connection"}</h2><p className="mt-0.5 text-xs text-slate-500 dark:text-slate-400">Expand each section to configure the connection.</p></div></div><button type="button" onClick={onClose} aria-label="Close form" className="rounded-lg p-2 text-slate-400 hover:bg-slate-100 dark:hover:bg-slate-800"><XMarkIcon className="h-5 w-5" /></button></header>
    <form onSubmit={onSubmit} className="space-y-3 p-3 sm:p-5">
      <Section title="Router and network" description="Select the router and configure its management endpoint." icon={<CpuChipIcon className="h-5 w-5" />} defaultOpen><Field label="MikroTik device"><select name="mikrotik" value={form.mikrotik} onChange={update} required className={inputClass}><option value="">Select device</option>{devices.map(device => <option key={device.id} value={device.id}>{device.identity_name}</option>)}</select></Field><div className="grid grid-cols-1 gap-3 sm:grid-cols-3"><div className="sm:col-span-2"><Field label="Management IP / hostname"><input name="management_ip" value={form.management_ip} onChange={update} required placeholder="10.0.0.20" className={inputClass} /></Field></div><Field label="API port"><input name="port" type="number" min={1} max={65535} value={form.port} onChange={update} required className={inputClass} /></Field></div></Section>
      <Section title="Authentication" description="Set the RouterOS API username and password." icon={<LockClosedIcon className="h-5 w-5" />}><Field label="API username"><input name="username" value={form.username} onChange={update} required autoComplete="username" placeholder="sys_admin" className={inputClass} /></Field><Field label="API password"><div className="relative"><input name="password" type={showPassword ? "text" : "password"} value={form.password} onChange={update} required={!editingConnection} autoComplete={editingConnection ? "new-password" : "current-password"} placeholder={editingConnection ? "Leave blank to keep current password" : "Enter API password"} className={`${inputClass} pr-11`} /><button type="button" onClick={() => setShowPassword(v => !v)} aria-label={showPassword ? "Hide password" : "Show password"} className="absolute right-2 top-1/2 -translate-y-1/2 rounded-lg p-2 text-slate-400 hover:bg-slate-200 dark:hover:bg-slate-700">{showPassword ? <EyeSlashIcon className="h-4 w-4" /> : <EyeIcon className="h-4 w-4" />}</button></div></Field></Section>
      <Section title="Hotspot portal" description="Optional hotspot server and captive portal login URL." icon={<LinkIcon className="h-5 w-5" />}><Field label="Hotspot server"><input name="hotspot_server" value={form.hotspot_server ?? ""} onChange={update} placeholder="hs-prof1" className={inputClass} /></Field><Field label="Hotspot login URL"><input name="hotspot_login_url" type="url" value={form.hotspot_login_url ?? ""} onChange={update} placeholder="http://10.0.0.1/login" className={inputClass} /></Field></Section>
      <Section title="Security and availability" description="Choose SSL API access and whether this connection is enabled." icon={<ShieldCheckIcon className="h-5 w-5" />}><label className="flex items-center justify-between gap-4 rounded-xl border border-sky-100 bg-sky-50/70 p-3.5 dark:border-slate-700 dark:bg-slate-800/70"><span className="flex items-center gap-3"><GlobeAltIcon className="h-5 w-5 text-sky-700 dark:text-sky-300" /><span><span className="block text-sm font-semibold text-slate-800 dark:text-slate-100">Use SSL</span><span className="mt-0.5 block text-xs text-slate-500 dark:text-slate-400">Uses port 8729 when enabled.</span></span></span><input type="checkbox" name="use_ssl" checked={form.use_ssl} onChange={update} className="h-5 w-5 rounded border-slate-300 text-sky-600 focus:ring-sky-500" /></label><label className="flex items-center justify-between gap-4 rounded-xl border border-emerald-100 bg-emerald-50/70 p-3.5 dark:border-slate-700 dark:bg-slate-800/70"><span><span className="block text-sm font-semibold text-slate-800 dark:text-slate-100">Connection enabled</span><span className="mt-0.5 block text-xs text-slate-500 dark:text-slate-400">Allow the application to use this connection.</span></span><input type="checkbox" name="enabled" checked={form.enabled} onChange={update} className="h-5 w-5 rounded border-slate-300 text-emerald-600 focus:ring-emerald-500" /></label></Section>
      <div className="sticky bottom-0 flex gap-2 border-t border-slate-200 bg-slate-50/95 pt-3 backdrop-blur sm:pt-4 dark:border-slate-800 dark:bg-gray-950/95"><button type="button" onClick={onClose} className="flex-1 rounded-xl border border-slate-200 bg-white px-4 py-3 text-sm font-semibold text-slate-700 hover:bg-slate-100 dark:border-slate-700 dark:bg-slate-900 dark:text-slate-200 dark:hover:bg-slate-800">Cancel</button><button type="submit" disabled={loading} className="flex-1 rounded-xl bg-gradient-to-r from-sky-600 to-emerald-600 px-4 py-3 text-sm font-bold text-white shadow-sm hover:brightness-105 disabled:cursor-not-allowed disabled:opacity-60">{loading ? "Saving..." : editingConnection ? "Save changes" : "Create connection"}</button></div>
    </form>
  </section></div>;
}
